from __future__ import annotations
from typing import Any, Mapping
from core.engineering.engineering_planning_common import freeze, seal, short_text
SCHEMA='zero.engineering.feedback_report.v1'; AUTHORITY_BOUNDARY={'approval':'not_granted','authorization':'not_granted','token':'not_granted','mutation':'not_granted','verification':'not_granted'}
def _ref(a:Mapping[str,Any], key:str)->dict[str,Any]: return {'identity':a.get(key) or a.get('artifact_identity'), 'fingerprint':a.get('fingerprint') or a.get('artifact_fingerprint'), 'schema':a.get('schema')}
def build_feedback_report(*, failure_analysis:Mapping[str,Any], eligibility:Mapping[str,Any], continuation_cycle:Mapping[str,Any], candidate:Mapping[str,Any]|None=None, plan:Mapping[str,Any]|None=None, proposal:Mapping[str,Any]|None=None, proposal_linkage:Mapping[str,Any]|None=None)->Mapping[str,Any]:
 body={'schema':SCHEMA,'task_id':failure_analysis.get('task_id'),'repository_identity':failure_analysis.get('repository_identity'),'parent_execution_session_id':failure_analysis.get('execution_session_id'),'failed_verification_result_identity':failure_analysis.get('verification_result_identity'),'failure_analysis_reference':_ref(failure_analysis,'failure_analysis_id'),'eligibility_reference':_ref(eligibility,'repair_continuation_eligibility_id'),'continuation_cycle_reference':_ref(continuation_cycle,'repair_continuation_cycle_id'),'candidate_reference':_ref(candidate or {},'candidate_id'),'plan_reference':_ref(plan or {},'repair_plan_id'),'proposal_reference':_ref(proposal or {},'proposal_id'),'proposal_linkage_reference':_ref(proposal_linkage or {},'proposal_linkage_id'),'failure_classification':failure_analysis.get('failure_classification'),'repairability':failure_analysis.get('repairability'),'cycle_number':eligibility.get('cycle_number'),'maximum_cycles':eligibility.get('maximum_cycles'),'remaining_cycles':eligibility.get('remaining_cycles'),'cycle_status':continuation_cycle.get('cycle_status'),'awaiting_human_approval':continuation_cycle.get('awaiting_human_approval') is True,'manual_intervention_required':continuation_cycle.get('cycle_status')=='manual_intervention_required' or eligibility.get('eligible') is False,'affected_target_count':len(failure_analysis.get('affected_target_paths') or []),'affected_operation_count':len(failure_analysis.get('affected_operation_ids') or []),'failed_expectation_count':len(failure_analysis.get('failed_expectation_ids') or []),'evidence_reference_count':len(failure_analysis.get('evidence_references') or []),'reason_codes':list(continuation_cycle.get('reason_codes') or eligibility.get('reason_codes') or []),'bounded_summary':short_text('Bounded feedback report contains references only; human approval remains required.',640),'deterministic':True,'immutable':True,'authority_boundary':AUTHORITY_BOUNDARY}
 return seal(body,'feedback_report_id','engineering-feedback-report')
